inline void safe_release(IUnknown*& resource) {
    if (resource) {
        resource->Release();
        resource = nullptr;
    }
}

inline void get_back_buffer(IDXGISwapChain* swap_chain) {
    ID3D11Texture2D* back_buffer = nullptr;
    if (FAILED(swap_chain->GetBuffer(0, IID_PPV_ARGS(&back_buffer))))
        return;

    D3D11_TEXTURE2D_DESC desc;
    back_buffer->GetDesc(&desc);
    desc.BindFlags = D3D11_BIND_SHADER_RESOURCE;

    ID3D11Texture2D* back_buffer_tex = nullptr;
    if (FAILED(device->CreateTexture2D(&desc, nullptr, &back_buffer_tex)))
        return;

    ctx->CopyResource(back_buffer_tex, back_buffer);

    D3D11_SHADER_RESOURCE_VIEW_DESC srvDesc = {};
    srvDesc.Format = desc.Format;
    srvDesc.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
    srvDesc.Texture2D.MipLevels = desc.MipLevels;
    srvDesc.Texture2D.MostDetailedMip = 0;

    safe_release(reinterpret_cast<IUnknown*&>(tex));
    device->CreateShaderResourceView(back_buffer_tex, &srvDesc, &tex);

    safe_release(reinterpret_cast<IUnknown*&>(back_buffer));
    safe_release(reinterpret_cast<IUnknown*&>(back_buffer_tex));
}

