inline void begin(const ImDrawList* d, const ImDrawCmd* cmd) {
    auto swap_chain = reinterpret_cast<IDXGISwapChain*>(cmd->UserCallbackData);
    auto bd = (ImGui_ImplDX11_Data*)ImGui::GetIO().BackendRendererUserData;

    get_back_buffer(swap_chain);

    if (!pshader || !pPixelBuffer || !pBlurSampler)
        compile_shader();

    ImVec2 uv_start = ImVec2(cmd->ClipRect.x / ImGui::GetIO().DisplaySize.x, cmd->ClipRect.y / ImGui::GetIO().DisplaySize.y);
    ImVec2 uv_end = ImVec2(cmd->ClipRect.z / ImGui::GetIO().DisplaySize.x, cmd->ClipRect.w / ImGui::GetIO().DisplaySize.y);
    float texel_width = 1.0f / ImGui::GetIO().DisplaySize.x;

    D3D11_MAPPED_SUBRESOURCE mapped;
    if (SUCCEEDED(ctx->Map(pPixelBuffer, 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped)))
    {
        float* data = (float*)mapped.pData;
        data[0] = uv_start.x;
        data[1] = uv_end.x;
        data[2] = texel_width;
        data[3] = 0.0f;
        ctx->Unmap(pPixelBuffer, 0);
    }

    ctx->PSSetShader(pshader, nullptr, 0);
    ctx->PSSetConstantBuffers(0, 1, &pPixelBuffer);
    ctx->PSSetShaderResources(0, 1, &tex);
    ctx->PSSetSamplers(0, 1, &pBlurSampler);

}

inline void release(const ImDrawList* d, const ImDrawCmd* cmd) {
    safe_release(reinterpret_cast<IUnknown*&>(tex));
}

inline void draw_background_blur(ImDrawList* draw_list, IDXGISwapChain* swap_chain, ID3D11Device* _device, ID3D11DeviceContext* _ctx, ImVec2 start, ImVec2 end, int rounding = 0, ImDrawFlags flags = 0) {
    device = _device;
    ctx = _ctx;

    draw_list->AddCallback(begin, swap_chain);

    ImVec2 uv_start = ImVec2(start.x / ImGui::GetIO().DisplaySize.x, start.y / ImGui::GetIO().DisplaySize.y);
    ImVec2 uv_end = ImVec2(end.x / ImGui::GetIO().DisplaySize.x, end.y / ImGui::GetIO().DisplaySize.y);

    draw_list->AddImageRounded((ImTextureID)tex, start, end, uv_start, uv_end, ImColor{ 1.f, 1.f, 1.f, 1.f }, rounding, flags);
    draw_list->AddCallback(ImDrawCallback_ResetRenderState, nullptr);
}
